Write documentation for the following method:
```
def ftp_remove_dir(ftp, path):
    for (name, properties) in ftp.mlsd(path=path):
        if name in ['.', '..']:
            continue
        elif properties['type'] == 'file':
            print("Delete file:", f"{path}/{name}")
            sleep(0.1)
            ftp.delete(f"{path}/{name}")
        elif properties['type'] == 'dir':
            print("Remove dir:", f"{path}/{name}")
            ftp_remove_dir(ftp, f"{path}/{name}")
    print("Remove final dir: ", path)
    ftp.rmd(path)
